-- === Проверка ===
SELECT priority, COUNT(*) FROM public.tasks GROUP BY priority ORDER BY priority;
SELECT shift, COUNT(*) FROM public.tasks GROUP BY shift;
SELECT
    date_trunc('hour', planned_start AT TIME ZONE 'Asia/Almaty') AS hour_local,
    COUNT(*) AS tasks
FROM public.tasks
GROUP BY 1 ORDER BY 1;
